use serde_json::Value;

pub fn solve(input: Value) -> Value {
    match input {
        Value::String(s) => {
            if s.is_empty() {
                return Value::Bool(false);
            }
            let mut chars = s.chars();
            if !chars.next().unwrap_or(' ').is_alphabetic() && chars.next().unwrap_or(' ') != '_' {
                return Value::Bool(false);
            }
            for c in chars {
                if !c.is_alphanumeric() && c != '_' {
                    return Value::Bool(false);
                }
            }
            Value::Bool(true)
        }
        _ => Value::Bool(false),
    }
}
